/**
 * Lean-owned data formats.
 *
 * TYPES come from `lean/generated/ehr-types.ts` (generated by `lake exe gents`
 * from lean/Ehr/Core/Types.lean and Json.lean): the single source of truth.
 * That file has no runtime validators yet, so the zod schemas below are
 * hand-written, but each is declared as `z.ZodType<Generated>`: if a schema
 * drifts from the Lean types, `tsc` fails. test/lean-types.test.ts also parses
 * the real Lean-written samples (lean/generated/ehr-samples.ts) and checks the
 * round trip is exact. Replace these schemas when Lean emits validators.
 *
 * JSON conventions (derived ToJson/FromJson): nullary constructors are
 * strings; constructors with named arguments are `{ "<ctor>": { ... } }`;
 * `Option` fields are `name?` keys, OMITTED when absent (we also accept `null`
 * on input, e.g. from an LLM, and drop it); products are 2-element arrays.
 *
 * Still MIRRORS (not generated yet): the `ehr min-clicks` output, and
 * component kinds added by vendor releases (`FutureKind`).
 */
import { z } from 'zod';
import type * as L from '../../lean/generated/ehr-types.js';

const nat = z.number().int().nonnegative();
const str = z.string();
const isObj = (x: unknown): x is Record<string, unknown> => typeof x === 'object' && x !== null && !Array.isArray(x);

/** Drop `null` values of the given optional keys (Lean omits absent options). */
function dropNulls<T extends z.ZodType>(keys: readonly string[], schema: T) {
  return z.preprocess((v) => {
    if (!isObj(v)) return v;
    const out: Record<string, unknown> = { ...v };
    for (const k of keys) if (out[k] === null) delete out[k];
    return out;
  }, schema);
}

// ---------------------------------------------------------------- spec
export const roleSchema: z.ZodType<L.Role> = z.enum(['physician', 'np', 'rn', 'surgeon']);
export const unitKindSchema: z.ZodType<L.UnitKind> = z.enum(['kg', 'lb', 'g', 'mg', 'mcg', 'mL', 'mgPerKg', 'units', 'none']);
const valueKindSchema: z.ZodType<L.ValueKind> = z.union([
  z.enum(['text', 'flag', 'identity', 'cosign']),
  z.looseObject({ quantity: z.looseObject({ unit: unitKindSchema }) }),
  z.looseObject({ coded: z.looseObject({ valueSet: str }) }),
  z.looseObject({ scan: z.looseObject({ target: str }) }),
]);
const elementSpecSchema: z.ZodType<L.ElementSpec> = dropNulls(['linkedFrom', 'recordFact'], z.looseObject({
  id: str, label: str, kind: valueKindSchema, enteredBy: z.array(roleSchema),
  prefill: z.enum(['never', 'recordConfirm', 'defaultConfirm', 'autoLinked']),
  friction: z.enum(['safety', 'compliance', 'accidental']),
  humanOnly: z.boolean(), linkedFrom: str.exactOptional(), recordFact: str.exactOptional(), fhirTarget: str,
}));
const whenSchema: z.ZodType<L.When> = z.union([
  z.enum(['always', 'highAlertMed', 'abnormalResult', 'naloxoneRisk', 'weightBased']),
  z.looseObject({ orderClass: z.looseObject({ cls: str }) }),
  z.looseObject({ drugClass: z.looseObject({ cls: str }) }),
  z.looseObject({ medClass: z.looseObject({ cls: str }) }),
  z.looseObject({ encounter: z.looseObject({ kind: str }) }),
]);
const reviewModeSchema: z.ZodType<L.ReviewMode> = z.union([
  z.literal('shownOnCommit'),
  z.looseObject({ shownOrReceipt: z.looseObject({ windowMin: nat, roles: z.array(roleSchema) }) }),
]);
export const specSchema: z.ZodType<L.Spec> = z.looseObject({
  version: str,
  elements: z.array(elementSpecSchema),
  infos: z.array(z.looseObject({ id: str, label: str, version: str })),
  commits: z.array(z.looseObject({ id: str, label: str, roles: z.array(roleSchema) })),
  entries: z.array(dropNulls(['allowed'], z.looseObject({ commit: str, element: str, when: whenSchema, perOrderLine: z.boolean(), allowed: z.array(str).exactOptional() }))),
  reviews: z.array(dropNulls(['waivedBy'], z.looseObject({ commit: str, info: str, mode: reviewModeSchema, when: whenSchema, waivedBy: str.exactOptional() }))),
  alerts: z.array(z.looseObject({
    id: str, label: str,
    cond: z.enum(['drugAllergy', 'interaction', 'duplicateTherapy', 'doseOutOfRange', 'weightInLb', 'careGap', 'highAlertMed']),
    tier: z.enum(['interruptive', 'passive', 'removable']), commit: str, screens: z.array(str),
  })),
  design: z.looseObject({ maxDepth: nat, minTextSize: nat, stabilityBudget: nat, landmarks: z.array(str), catalog: z.array(str) }),
});

// ---------------------------------------------------------------- programs
/**
 * MIRROR: a component kind added by a vendor release (e.g. v1.1
 * `priorAuthStatus`) before the generated union knows it. One constructor key.
 */
export type FutureKind = { [ctor: string]: unknown };
export type Kind = L.Kind | FutureKind;
export type Component = Omit<L.Component, 'kind'> & { kind: Kind };
export type Screen = Omit<L.Screen, 'components'> & { components: Component[] };
export type Program = Omit<L.Program, 'screens' | 'componentDefs'> & { screens: Screen[]; componentDefs?: { name: string; params: string[]; body: Component[] }[] };

const slotSchema: z.ZodType<L.Slot> = z.union([z.literal('current'), z.object({ fixed: z.object({ n: nat }) })]);
const prefillSchema: z.ZodType<L.Prefill> = z.union([
  z.literal('none'),
  z.object({ fromRecord: z.object({ fact: str }) }),
  z.object({ default: z.object({ value: str }) }),
  z.object({ linked: z.object({ element: str }) }),
]);
const actionSchema: z.ZodType<L.Action> = z.union([
  z.enum(['back', 'newOrderLine', 'requestPriorAuth']),
  z.object({ goto: z.object({ screen: str }) }),
  z.object({ commit: z.object({ commit: str }) }),
  z.object({ markReviewed: z.object({ info: str }) }),
]);
const knownKindSchema: z.ZodType<L.Kind> = z.union([
  z.enum(['banner', 'tabs']),
  z.object({ field: z.object({ element: str, slot: slotSchema, prefill: prefillSchema }) }),
  z.object({ panel: z.object({ info: str }) }),
  z.object({ table: z.object({ info: str }) }),
  z.object({ trend: z.object({ info: str }) }),
  z.object({ alert: z.object({ alert: str, popup: z.boolean() }) }),
  z.object({ button: z.object({ action: actionSchema }) }),
  z.object({ group: z.object({ collapsible: z.boolean(), startCollapsed: z.boolean() }) }),
  z.object({ macro: z.object({ id: str }) }),
  z.object({ search: z.object({ scope: str }) }),
  z.object({ priorAuth: z.object({ info: str }) }),
]);
const KNOWN_KINDS = new Set(['banner', 'tabs', 'field', 'panel', 'table', 'trend', 'alert', 'button', 'group', 'macro', 'search', 'priorAuth']);
const futureKindSchema: z.ZodType<FutureKind> = z.record(str, z.unknown()).refine(
  (o) => Object.keys(o).length === 1 && !KNOWN_KINDS.has(Object.keys(o)[0] ?? ''),
  { message: 'not a valid component kind' },
);
export const kindSchema: z.ZodType<Kind> = z.union([knownKindSchema, futureKindSchema]);

export const componentSchema: z.ZodType<Component> = dropNulls(['parent', 'hotkey', 'copyOf'], z.object({
  id: str.min(1),
  kind: kindSchema,
  label: str.default(''),
  parent: str.exactOptional(),
  tab: nat.default(0),
  visibility: z.union([z.literal('always'), z.object({ unlessReceipt: z.object({ info: str }) })]).default('always'),
  size: z.enum(['normal', 'compact', 'tiny']).default('normal'),
  hotkey: str.exactOptional(),
  tag: str.default(''),
  copyOf: str.exactOptional(),
}));
const macroStepSchema: z.ZodType<L.MacroStep> = z.union([
  z.object({ setValue: z.object({ comp: str, value: str }) }),
  z.object({ click: z.object({ comp: str }) }),
  z.object({ goto: z.object({ screen: str }) }),
]);
export const programSchema: z.ZodType<Program> = z.object({
  id: str.min(1),
  version: nat,
  owner: str,
  role: roleSchema,
  specVersion: str,
  start: str,
  screens: z.array(z.object({ id: str.min(1), title: str, workflow: str, components: z.array(componentSchema) })),
  macros: z.array(z.object({ id: str.min(1), label: str, steps: z.array(macroStepSchema) })),
  componentDefs: z.array(z.object({ name: str.min(1), params: z.array(str), body: z.array(componentSchema) })).exactOptional(),
});

// ---------------------------------------------------------------- events
const valueSchema: z.ZodType<L.Value> = z.union([
  z.object({ qty: z.object({ tenths: nat, unit: unitKindSchema }) }),
  z.object({ code: z.object({ c: str }) }),
  z.object({ text: z.object({ s: str }) }),
  z.object({ flag: z.object({ b: z.boolean() }) }),
  z.object({ user: z.object({ u: str }) }),
]);
export const eventSchema: z.ZodType<L.Event> = z.union([
  z.object({ click: z.object({ comp: str }) }),
  z.object({ selectTab: z.object({ comp: str, idx: nat }) }),
  z.object({ enter: z.object({ comp: str, value: valueSchema }) }),
  z.object({ confirm: z.object({ comp: str }) }),
  z.object({ ack: z.object({ alert: str }) }),
  z.object({ scroll: z.object({ screen: str }) }),
  z.object({ search: z.object({ query: str }) }),
]);
const stepResultSchema: z.ZodType<L.StepResult> = z.union([z.enum(['ok', 'ignored']), z.object({ blocked: z.object({ reason: str }) })]);

// ---------------------------------------------------------------- simulation
const orderChoiceSchema: z.ZodType<L.OrderChoice> = dropNulls(['indication', 'kind', 'code', 'supplyDays', 'curesExemptReason', 'holdReason'], z.object({
  drug: str, doseTenths: nat, unit: unitKindSchema, route: str, freq: str, indication: str.exactOptional(), prn: z.boolean(),
  kind: z.enum(['medication', 'imaging', 'procedure']).exactOptional(), code: str.exactOptional(),
  supplyDays: nat.exactOptional(), curesExemptReason: str.exactOptional(), holdReason: str.exactOptional(),
}));
const taskSchema: z.ZodType<L.Task> = z.object({
  id: str,
  day: nat,
  persona: str,
  workflow: z.enum(['W1', 'W2', 'W3', 'W4', 'W5', 'W6', 'W7']),
  patientId: str,
  startMin: nat,
  choices: dropNulls(['refill', 'disposition', 'painScore', 'w6Step', 'refillReason'], z.object({
    orders: z.array(orderChoiceSchema), administer: z.array(orderChoiceSchema), ackResult: z.boolean(),
    refill: str.exactOptional(), disposition: str.exactOptional(), immunizations: z.array(str), noteSections: z.array(str),
    painScore: nat.exactOptional(), w6Step: z.enum(['consult', 'preop', 'postop', 'rounding', 'discharge']).exactOptional(),
    refillReason: str.exactOptional(),
  })),
  todayResources: z.array(z.unknown()),
  interruptions: nat,
});
export const dayScheduleSchema: z.ZodType<L.DaySchedule> = z.object({ day: nat, persona: str, load: str, tasks: z.array(taskSchema) });
export const personaParamsSchema: z.ZodType<L.PersonaParams> = z.object({
  id: str, role: roleSchema, keyboardShare: nat, reviewsAllergiesEarly: z.boolean(), scansSidebar: z.boolean(),
  backtrackRate: nat, searchWhenBuried: z.boolean(), overrideRate: nat,
});
const taskMetricsSchema: z.ZodType<L.TaskMetrics> = z.object({
  task: str, clicks: nat, keystrokes: nat, scrolls: nat, popups: nat, overrides: nat, searches: nat, backtracks: nat,
  klmDeciSec: nat, completed: z.boolean(),
});
export const dayResultSchema: z.ZodType<L.DayResult> = z.object({
  day: nat,
  persona: str,
  programVersion: nat,
  trace: z.array(z.object({
    task: str, t: nat, screen: str, event: eventSchema,
    ops: z.array(z.enum(['click', 'key', 'scroll', 'scan', 'point', 'think', 'wait'])), result: stepResultSchema,
  })),
  tasks: z.array(taskMetricsSchema),
  floor: z.array(taskMetricsSchema),
  complaints: z.array(str),
});

// ---------------------------------------------------------------- checker
export type Verdict = L.Verdict;
export type Violation = Extract<L.Verdict, { violation: unknown }>['violation'];
export const violationSchema: z.ZodType<Violation> = z.object({
  property: str, message: str, counterexample: z.array(eventSchema), screens: z.array(str),
});
export const verdictSchema: z.ZodType<L.Verdict> = z.union([z.literal('ok'), z.object({ violation: violationSchema })]);
export const certificateSchema: z.ZodType<L.Certificate> = z.object({
  specVersion: str, specHash: str, programHash: str, verdict: verdictSchema, checkerVersion: str, time: str,
});

/**
 * MIRROR (ASSUMED format, not generated yet): `ehr min-clicks` output. One
 * row per task of the schedule; exact minimum over completing paths (T9).
 */
export interface MinClicksRow { task: string; workflow?: string; clicks: number; keystrokes: number }
export interface MinClicksResult { tasks: MinClicksRow[] }
export const minClicksResultSchema: z.ZodType<MinClicksResult> = z.object({
  tasks: z.array(dropNulls(['workflow'], z.object({ task: str, workflow: str.exactOptional(), clicks: nat, keystrokes: nat }))),
});

export type Role = L.Role;
export type Spec = L.Spec;
export type ElementSpec = L.ElementSpec;
export type Macro = L.Macro;
export type Event = L.Event;
export type Workflow = L.Workflow;
export type Task = L.Task;
export type DaySchedule = L.DaySchedule;
export type PersonaParams = L.PersonaParams;
export type TraceEvent = L.TraceEvent;
export type TaskMetrics = L.TaskMetrics;
export type DayResult = L.DayResult;
export type Certificate = L.Certificate;

export function violationOf(verdict: Verdict): Violation | null {
  return verdict === 'ok' ? null : verdict.violation;
}

/** Compile-time check: everything Lean emits is accepted by the agent's widened Program. */
export const acceptsGenerated = (p: L.Program): Program => p;
